 public static void main(String[] args){String[][] cases={{"friend_recommendation","recommendation"},{"social_post","post"},{"chat_message","chat"},{"CHAT_MESSAGE","chat"},{"chat_group_message","group"},{"convite","friends"},{"amizade_aceita","friendProfile"},{"chat_group_invite","groups"},{"social_like","post"},{"social_comment","post"},{"social_reply","post"},{"conquista","achievements"},{"nivel","profile"},{"missao","missions"},{"other","inbox"},{"https://evil.test","inbox"},{null,"inbox"}};for(String[] c:cases)if(!NotificationRoute.destination(c[0]).equals(c[1]))throw new AssertionError(c[0]);if(NotificationRoute.opensComments("social_post")||NotificationRoute.opensComments("social_like")||!NotificationRoute.opensComments("social_comment")||!NotificationRoute.opensComments("social_reply"))throw new AssertionError("Comment navigation");System.out.println("21 notification routing checks passed.");}
